Q7 = READ(7, "निम्नलिखित पठित गद्यांश के आधार पर बहुविकल्पीय प्रश्नों के सर्वाधिक उपयुक्त उत्तर विकल्प चुनकर लिखिए: (5×1=5)<br><small>(पाठ ‘बालगोबिन भगत’ पर आधारित गद्यांश)</small>",
 "<p>भगत जी की दिनचर्या में कोई ढील नहीं आती थी। भोर के अँधेरे में उठकर वे गाँव के बाहर के तालाब पर नहाने जाते और लौटते हुए ऐसा गाना छेड़ते कि सोए हुए खेत भी जाग उठते। माथे पर रामानंदी चंदन का टीका, गले में तुलसी की जड़ों की माला और कमर में लंगोटी — बस इतना ही उनका शृंगार था। घर में खेती-बारी थी, पर वे किसी की चीज़ को बिना पूछे हाथ नहीं लगाते थे। कबीर को वे अपना ‘साहब’ मानते थे और उन्हीं के पदों को गाकर मन बहलाते थे। खेत में जो कुछ उपजता, उसे पहले कबीरपंथी मठ में ले जाकर ‘साहब’ के दरबार में रख आते और वहाँ से प्रसाद-रूप में जो मिलता, उसी से घर चलाते।</p>",
 [sub(M("गद्यांश के अनुसार भगत जी भोर में क्या करते थे?", ["खेतों में हल चलाते थे", "तालाब पर नहाने जाकर लौटते हुए गाना गाते थे", "मठ में प्रवचन देते थे", "बाज़ार में अनाज बेचते थे"], 1), 1),
  sub(ST("खेत की उपज के संबंध में सही कथनों का चयन कीजिए:", ["उपज को पहले कबीरपंथी मठ में ले जाया जाता था।", "उपज को सीधे बाज़ार में बेच दिया जाता था।", "मठ से मिले प्रसाद से घर का खर्च चलता था।", "उपज पूरी तरह दान में बाँट दी जाती थी।"], (0, 2)), 1),
  sub(AR("भगत जी किसी की चीज़ को बिना पूछे हाथ नहीं लगाते थे।", "वे ईमानदार और संयमी स्वभाव के व्यक्ति थे।", 2), 1, "कथन और कारण दोनों सही हैं; ईमानदारी ही आचरण का कारण है।"),
  sub(M("‘कबीर को वे अपना साहब मानते थे’ — इससे भगत जी के बारे में क्या प्रकट होता है?", ["कबीर के प्रति गहरी श्रद्धा और आस्था", "साहब बनने की इच्छा", "नौकरी के प्रति लगाव", "कबीर से भय"], 0), 1),
  sub(ST("गद्यांश के आधार पर भगत जी के व्यक्तित्व के कौन-से गुण झलकते हैं?", ["नियमबद्धता", "आलस्य", "सादगी", "संतोष"], (0, 2, 3)), 1)])
